import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as s,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"The Codex Product Line","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/codex/codex-ai.md","filePath":"products/ai-coding/codex/codex-ai.md","lastUpdated":1787048027000}'),n={name:"products/ai-coding/codex/codex-ai.md"};function i(r,e,d,l,c,h){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="the-codex-product-line" tabindex="-1">The Codex Product Line <a class="header-anchor" href="#the-codex-product-line" aria-label="Permalink to &quot;The Codex Product Line&quot;">​</a></h1><blockquote><p>Codex is not one program. It is one agent reachable through four surfaces, sharing one configuration. This page maps the surfaces and explains what each is for — read it before deciding where a given task belongs.</p><p>Concept definitions live in the <a href="./codex-glossary.html">Glossary</a>; this page is about product shape.</p></blockquote><h2 id="what-codex-is" tabindex="-1">What Codex is <a class="header-anchor" href="#what-codex-is" aria-label="Permalink to &quot;What Codex is&quot;">​</a></h2><p>From the official documentation:</p><blockquote><p>Codex is OpenAI&#39;s coding agent for software development.</p></blockquote><p>The word that matters is <em>agent</em>. A completion tool suggests the next line; an agent reads your files, runs your commands, and iterates on the result. That difference drives everything else on this page — the sandbox, the approval policy, and the trust model all exist because Codex acts rather than suggests.</p><p>The documented capabilities are five:</p><table tabindex="0"><thead><tr><th>Capability</th><th>What it means in practice</th></tr></thead><tbody><tr><td><strong>Write code</strong></td><td>Matches your intent and adapts to the existing project structure and conventions</td></tr><tr><td><strong>Understand unfamiliar codebases</strong></td><td>Reads and explains code it has never seen before</td></tr><tr><td><strong>Review code</strong></td><td>Finds potential bugs, logic errors, and unhandled edge cases</td></tr><tr><td><strong>Debug and fix problems</strong></td><td>Traces failures, diagnoses root causes, applies targeted fixes</td></tr><tr><td><strong>Automate development tasks</strong></td><td>Refactoring, testing, migrations, project setup</td></tr></tbody></table><h2 id="four-surfaces-one-configuration" tabindex="-1">Four surfaces, one configuration <a class="header-anchor" href="#four-surfaces-one-configuration" aria-label="Permalink to &quot;Four surfaces, one configuration&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌──────────────────────────────┐</span></span>
<span class="line"><span>                    │   ~/.codex/config.toml       │</span></span>
<span class="line"><span>                    │   AGENTS.md · Rules          │</span></span>
<span class="line"><span>                    │   MCP · Skills · Hooks       │</span></span>
<span class="line"><span>                    └───────────┬──────────────────┘</span></span>
<span class="line"><span>                                │  same configuration</span></span>
<span class="line"><span>        ┌───────────────┬───────┴───────┬───────────────┐</span></span>
<span class="line"><span>        │               │               │               │</span></span>
<span class="line"><span>   ┌────▼────┐    ┌─────▼─────┐   ┌─────▼─────┐   ┌─────▼─────┐</span></span>
<span class="line"><span>   │   CLI   │    │    IDE    │   │  Desktop  │   │   Cloud   │</span></span>
<span class="line"><span>   │ \`codex\` │    │ extension │   │    app    │   │  / Web    │</span></span>
<span class="line"><span>   └─────────┘    └───────────┘   └───────────┘   └───────────┘</span></span>
<span class="line"><span>   terminal        in-editor       GUI, local      remote,</span></span>
<span class="line"><span>   scriptable      context         browser, etc.   parallel</span></span></code></pre></div><p>That shared configuration is the point. An <code>AGENTS.md</code> you write for the CLI governs the IDE extension too. A sandbox mode you set applies everywhere. You learn the model once.</p><h3 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h3><p>The terminal surface, and the one this tutorial focuses on. It is the only surface that is fully scriptable, which makes it the surface for automation.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                    # interactive</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;run the tests and fix failures&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # one-shot, non-interactive</span></span></code></pre></div><p>Choose the CLI when the task is scriptable, when you are already in a terminal, or when it needs to run in CI.</p><p>Reference: <a href="https://learn.chatgpt.com/docs/codex/cli" target="_blank" rel="noreferrer">CLI documentation</a></p><h3 id="ide-extension" tabindex="-1">IDE extension <a class="header-anchor" href="#ide-extension" aria-label="Permalink to &quot;IDE extension&quot;">​</a></h3><p>Runs inside your editor, with the editor&#39;s notion of what file and selection you are looking at.</p><p>Choose the IDE extension when the task is anchored to code you are currently reading — the editor already knows the context you would otherwise have to describe.</p><p>Reference: <a href="https://learn.chatgpt.com/docs/codex/ide" target="_blank" rel="noreferrer">IDE Extension documentation</a> · this guide’s <a href="./codex-ide.html">IDE tutorial</a></p><h3 id="desktop-app" tabindex="-1">Desktop app <a class="header-anchor" href="#desktop-app" aria-label="Permalink to &quot;Desktop app&quot;">​</a></h3><p>On 2026-07-09 the standalone Codex app merged into the <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT desktop app</a>. Updating the old Codex app leaves Chat, Work, and Codex in one window. You can still default to the Codex view and keep the Codex icon.</p><p>The graphical surface has what the terminal does not: an in-app browser, worktrees, local environments, a PR sidebar, multi-repo projects, Computer Use. Choose desktop Codex when a browser belongs in the loop or you want several tasks visible — and do not confuse it with <a href="./chatgpt-work.html">ChatGPT Work</a>. Work hides Git / shell detail and has no PR pane.</p><h3 id="cloud-web-and-hosted-review" tabindex="-1">Cloud, web, and hosted review <a class="header-anchor" href="#cloud-web-and-hosted-review" aria-label="Permalink to &quot;Cloud, web, and hosted review {#cloud-web-and-hosted-review}&quot;">​</a></h3><p>Runs the agent on OpenAI&#39;s infrastructure against a configured environment rather than your laptop. Product entry: <a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a>. Docs: <a href="https://learn.chatgpt.com/docs/cloud" target="_blank" rel="noreferrer">Codex cloud</a>. Tutorial: <a href="./codex-cloud.html">Codex Cloud</a>. Phone control of a <strong>local</strong> host is <a href="./codex-remote.html">Remote</a>, not Cloud.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                            # browse environments (Ctrl+O reveals IDs)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ENV_I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;run the migration dry run&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ENV_I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --attempts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 1-4 attempts</span></span></code></pre></div><p>Official “use Cloud when…” list:</p><ul><li>The job should run in the background without tying up the laptop</li><li>You want several attempts in parallel</li><li>The work starts in <strong>GitHub, Linear, or Slack</strong></li><li>You are away from the development machine and only have the web UI or CLI</li></ul><p>Setup: sign in → connect GitHub → create an environment in <a href="https://chatgpt.com/codex/settings/environments" target="_blank" rel="noreferrer">environment settings</a> → start a task → review the summary and diff → open a PR if it is ready. Environment details: <a href="https://learn.chatgpt.com/docs/environments/cloud-environment" target="_blank" rel="noreferrer">Cloud environments</a>.</p><p><strong>Hosted review is not a fourth product.</strong> It is Cloud / web review:</p><table tabindex="0"><thead><tr><th>Surface</th><th>What it does</th><th>Source</th></tr></thead><tbody><tr><td>Local <code>/review</code></td><td>Base-branch or uncommitted diff; does not change the tree</td><td>CLI / IDE / desktop</td></tr><tr><td>Codex cloud code review / QA</td><td>Review and QA in the hosted environment</td><td><a href="https://learn.chatgpt.com/docs/whats-new" target="_blank" rel="noreferrer">What&#39;s new</a> (week of 2026-07-27): <strong>GPT-5.6 Sol</strong> for eligible customers; Cloud <strong>selects the model automatically</strong>; Terra / Luna remain on local and web surfaces</td></tr><tr><td>Codex Security Review</td><td>PR changes plus repo context and threat model; auto on open/push or <code>@codex security review</code></td><td>Research preview; Enterprise / Business / Edu / Pro; <strong>not Plus</strong></td></tr></tbody></table><p>Do not give hosted review its own page: it is a Cloud workflow. Config and quota still come from the plan and the cloud environment.</p><blockquote><p>Documentation pages use a <code>?surface=cli|app|ide</code> selector. If a page seems to describe features you don&#39;t have, check which surface is selected.</p></blockquote><h2 id="how-a-run-actually-proceeds" tabindex="-1">How a run actually proceeds <a class="header-anchor" href="#how-a-run-actually-proceeds" aria-label="Permalink to &quot;How a run actually proceeds&quot;">​</a></h2><p>Understanding the sequence explains most surprising behavior.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Build the instruction chain</span></span>
<span class="line"><span>   global AGENTS.md → project AGENTS.md chain (root → cwd)</span></span>
<span class="line"><span>   Rebuilt every run. No cache.</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>2. Load configuration layers</span></span>
<span class="line"><span>   ~/.codex/config.toml → profile → trusted project .codex/ → CLI flags</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>3. Read the prompt, plan</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>4. Act: read files, run commands, call MCP tools</span></span>
<span class="line"><span>   Every action filtered through: sandbox_mode → approval_policy → hooks</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>5. Report, and iterate if verification failed</span></span></code></pre></div><p>Three consequences worth internalizing:</p><ul><li><strong>Instruction files are re-read every run</strong>, so editing <code>AGENTS.md</code> takes effect on the next invocation with nothing to flush.</li><li><strong>Project configuration only loads for trusted projects.</strong> If <code>.codex/config.toml</code> seems inert, that is the first thing to check.</li><li><strong>The sandbox is checked before the approval policy.</strong> A read-only sandbox cannot be talked into writing, no matter how the approval policy is set.</li></ul><h2 id="where-codex-sits-among-coding-tools" tabindex="-1">Where Codex sits among coding tools <a class="header-anchor" href="#where-codex-sits-among-coding-tools" aria-label="Permalink to &quot;Where Codex sits among coding tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Completion tools</th><th>IDE-integrated agents</th><th>Terminal agents</th></tr></thead><tbody><tr><td><strong>Unit of work</strong></td><td>Next few lines</td><td>A file or selection</td><td>A task across files</td></tr><tr><td><strong>Runs commands</strong></td><td>No</td><td>Sometimes</td><td>Yes</td></tr><tr><td><strong>Scriptable / CI</strong></td><td>No</td><td>Rarely</td><td>Yes</td></tr><tr><td><strong>You review</strong></td><td>Each suggestion</td><td>Each edit</td><td>The resulting diff</td></tr><tr><td><strong>Examples</strong></td><td>Copilot completions</td><td>Cursor, Copilot agent mode</td><td><strong>Codex CLI</strong>, Claude Code</td></tr></tbody></table><p>Codex spans more than one column — the IDE extension sits in the middle, the CLI in the right — but the CLI is where its distinctive capabilities live: non-interactive execution, sandbox modes, subagents, and cloud offload.</p><p>Practical selection guidance:</p><ul><li><strong>Typing code yourself and want it faster</strong> → a completion tool</li><li><strong>Changing code you&#39;re currently reading</strong> → IDE extension</li><li><strong>A task described in a sentence, spanning several files</strong> → Codex CLI</li><li><strong>Something that must run without a human present</strong> → <code>codex exec</code></li><li><strong>Deep in the OpenAI ecosystem already</strong> → Codex, since access comes with your ChatGPT plan</li></ul><h2 id="the-extension-surface" tabindex="-1">The extension surface <a class="header-anchor" href="#the-extension-surface" aria-label="Permalink to &quot;The extension surface&quot;">​</a></h2><p>Codex is extended at five distinct points. Knowing which one to reach for is most of the skill.</p><table tabindex="0"><thead><tr><th>Point</th><th>Nature</th><th>Use when</th></tr></thead><tbody><tr><td><strong>AGENTS.md</strong></td><td>Natural-language briefing</td><td>You can state it in prose</td></tr><tr><td><strong>Rules</strong></td><td>Structured constraint</td><td>It must be enforceable, not advisory</td></tr><tr><td><strong>MCP</strong></td><td>External tools and data</td><td>The agent needs to reach outside the machine</td></tr><tr><td><strong>Skills</strong></td><td>Packaged workflow</td><td>A procedure repeats and is worth naming</td></tr><tr><td><strong>Hooks</strong></td><td>Command on a lifecycle event</td><td>It must happen deterministically</td></tr><tr><td><strong>Subagents</strong></td><td>Delegated agent</td><td>A sub-task deserves its own context</td></tr><tr><td><strong>Plugins</strong></td><td>Distribution bundle</td><td>More than one person needs the above</td></tr></tbody></table><p>The load-bearing distinction: <strong><code>AGENTS.md</code> is advice the model may weigh against other instructions; a hook is mechanism that runs regardless.</strong> If a step must not be skipped, it is a hook.</p><p>Hook events: <code>PreToolUse</code>, <code>PermissionRequest</code>, <code>PostToolUse</code>, <code>PreCompact</code>, <code>PostCompact</code>, <code>SessionStart</code>, <code>SubagentStart</code>, <code>SubagentStop</code>, <code>UserPromptSubmit</code>, <code>Stop</code>. Only command hooks execute today — prompt and agent hooks are parsed but skipped.</p><p>See <a href="./codex-cookbook.html#part-8-choosing-an-extension-point">Choosing an extension point</a> for the decision rules.</p><h2 id="security-model" tabindex="-1">Security model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security model&quot;">​</a></h2><p>Three layers, checked in order, and the first one is mechanical rather than advisory.</p><p><strong>Sandbox</strong> — <code>read-only</code>, <code>workspace-write</code>, or <code>danger-full-access</code>. This is a hard boundary on file and network access. <code>workspace-write</code> is the everyday default; <code>read-only</code> is what makes an adversarial review session trustworthy.</p><p><strong>Approval policy</strong> — <code>untrusted</code>, <code>on-request</code>, <code>never</code>, or a granular table. This controls whether Codex pauses to ask before acting. In the TUI these appear as <code>Auto</code>, <code>Read-only</code>, and <code>Full Access</code> via <code>/permissions</code>.</p><p><strong>Project trust</strong> — <code>projects.&lt;path&gt;.trust_level</code>. An untrusted project&#39;s <code>.codex/</code> layers are not loaded at all: no project config, no project hooks, no project rules. This is the layer that protects you when you clone a repository you have not read.</p><blockquote><p><code>--yolo</code> sets full access and also switches web search to live. It is a real flag and it exists for a reason, but it disables the layer that would otherwise contain a mistake. Reach for <code>--ask-for-approval never</code> with a normal sandbox first — it stops the prompting without removing the boundary.</p></blockquote><h2 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Models&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gpt-5.6&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_reasoning_effort = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;medium&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # minimal | low | medium | high | xhigh</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_reasoning_summary = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # auto | concise | detailed | none</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_verbosity = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;medium&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # low | medium | high</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">review_model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gpt-5.6&quot;</span></span></code></pre></div><p><code>gpt-5.6</code> is the model named in the current <a href="https://learn.chatgpt.com/docs/config-file/config-basic" target="_blank" rel="noreferrer">config basics</a> example. The 5.6 family on the pricing page is Sol / Terra / Luna. ChatGPT Pro additionally has <code>GPT-5.3-Codex-Spark</code> as a research preview. <code>model_reasoning_effort</code> applies to the Responses API. Model names change; check <a href="https://learn.chatgpt.com/docs/models" target="_blank" rel="noreferrer">Models</a> rather than trusting any tutorial including this one.</p><p><code>review_model</code> lets a review run use a different model from the writing run — useful if you want a stronger model doing the critique.</p><p>The authoritative list is <a href="https://learn.chatgpt.com/docs/models" target="_blank" rel="noreferrer">Models</a>. Model names change; check there rather than trusting any tutorial including this one.</p><h2 id="capabilities-and-limits" tabindex="-1">Capabilities and limits <a class="header-anchor" href="#capabilities-and-limits" aria-label="Permalink to &quot;Capabilities and limits&quot;">​</a></h2><p><strong>Reliable at:</strong> reading unfamiliar code, mechanical multi-file changes, writing tests against a stated contract, tracing a failure from a reproduction command, translating between conventions.</p><p><strong>Needs supervision for:</strong> architectural decisions with long-lived consequences, anything where &quot;correct&quot; depends on business context not in the repository, performance work requiring real measurement, security-sensitive changes.</p><p><strong>Structurally cannot do:</strong> know things absent from your repository and its instruction files, verify anything it cannot run, or be sure a change is safe without a test that proves it.</p><p>The last point is the practical one. Almost every disappointing Codex session traces back to accepting a change that was never executed. The fix is one sentence in the prompt: <em>run the tests and show me the output.</em></p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Learning Map</a> — family tree and decision tree</li><li><a href="./codex-cli.html">Codex CLI</a> — installation and core features</li><li><a href="./chatgpt-work.html">ChatGPT Work</a> — knowledge-work agent (not Codex)</li><li><a href="./chatgpt-plus.html">ChatGPT Plans and Codex Access</a> — how access works</li><li><a href="./integration.html">Project Integration</a> — wiring Codex into a real project</li><li><a href="./codex-cookbook.html">Codex Cookbook</a> — task recipes</li><li><a href="./codex-glossary.html">Codex Glossary</a> — concept definitions</li><li><a href="./codex-cheatsheet.html">Codex Cheatsheet</a> — quick lookup</li></ul><h2 id="official-sources" tabindex="-1">Official sources <a class="header-anchor" href="#official-sources" aria-label="Permalink to &quot;Official sources&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/docs" target="_blank" rel="noreferrer">Codex documentation</a></li><li><a href="https://learn.chatgpt.com/docs/codex/cli" target="_blank" rel="noreferrer">CLI</a> · <a href="https://learn.chatgpt.com/docs/codex/ide" target="_blank" rel="noreferrer">IDE</a> · <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">App</a></li><li><a href="https://learn.chatgpt.com/docs/cloud" target="_blank" rel="noreferrer">Codex cloud</a> · <a href="https://learn.chatgpt.com/docs/code-review" target="_blank" rel="noreferrer">Code review</a></li><li><a href="https://learn.chatgpt.com/docs/sandboxing" target="_blank" rel="noreferrer">Sandboxing</a> · <a href="https://learn.chatgpt.com/docs/permissions" target="_blank" rel="noreferrer">Permissions</a></li><li><a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Configuration Reference</a></li><li><a href="https://learn.chatgpt.com/docs/models" target="_blank" rel="noreferrer">Models</a> · <a href="https://learn.chatgpt.com/docs/feature-maturity" target="_blank" rel="noreferrer">Feature Maturity</a></li><li><a href="https://learn.chatgpt.com/docs/whats-new" target="_blank" rel="noreferrer">What&#39;s new</a></li></ul>`,69)])])}const f=t(n,[["render",i]]);export{k as __pageData,f as default};
